update vm_uav_device_info_t
set uav_nest_code = #{uavNestCode}
where device_code = #{uavDeviceCode}

update vm_uav_nest_device_info
set
update_time = now()

    ,altitude = #{altitude}


    ,calibration_status = #{calibration}



    ,longitude = #{longitude}


    ,latitude = #{latitude}


    ,lat_lon_update_time = #{latLonUpdateTime}

where device_code = #{uavNestCode}
